// Üretilen dosya: tool/ozgun/uret.py. Matematik ve Geometri · Katı cisimler ve uzay geometrisi: prizma, piramit, silindir, koni, küre, kesit ve açınım problemleri (zor).
const ozMathematics17Zor = <(String, String, List<String>, String)>[
  ('Yan ayrıtı 12 cm olan ve her bir yan yüzündeki ikizkenar üçgenin tepe açısı 15° olan düzgün kare piramidin taban köşesi A\'dan başlayıp 4 yan yüzü dolaşarak TA yan ayrıtının orta noktası M\'ye giden karıncanın en kısa yolu kaç santimetredir?', '6√3 santimetre', ['6√5 santimetre', '6√7 santimetre', '12 santimetre'], 'Dört yan yüz açıldığında tepe açısı 4 × 15° = 60° olur. Kenarları TA = 12 cm ve TM = 6 cm, aradaki açı 60° olan üçgende kosinüs teoreminden AM² = 12² + 6² - 2×12×6×cos60° = 144 + 36 - 72 = 108 ve AM = 6√3 cm bulunur.'),
  ('Taban ayrıtları AB = 9 cm, BC = 20 cm ve yüksekliği CG = 12 cm olan ABCDEFGH dikdörtgenler prizmasında D köşesinden AG cisim köşegenine indirilen dikmenin uzunluğu kaç santimetredir?', '12 santimetre', ['9,6 santimetre', '15 santimetre', '10,8 santimetre'], 'AD = BC = 20 cm ayrıtı DCGH düzlemine diktir, dolayısıyla AD ⊥ DG olur. DC = 9 cm ve CG = 12 cm olduğundan DG = 15 cm\'dir. ADG dik üçgeninde dik kenarlar 15 cm ve 20 cm, hipotenüs AG = 25 cm olduğundan dikme (15 × 20) / 25 = 12 cm bulunur.'),
  ('Boyutları 8 cm, 10 cm ve 16 cm olan kapalı bir dikdörtgenler prizması kabı, en küçük yüzeyi olan 8×10 tabanı üzerindeyken içinde h yüksekliğinde su vardır. Kap en büyük yüzeyi olan 10×16 tabanı üzerine yatırıldığında su yüksekliği ilk duruma göre 6 cm azaldığına göre başlangıçtaki h yüksekliği kaç santimetredir?', '12 santimetre', ['10 santimetre', '14 santimetre', '9 santimetre'], 'Su hacmi eşitliğinden 8 × 10 × h = 10 × 16 × (h - 6) yazılır; buradan 80h = 160(h - 6), h = 2h - 12 ve h = 12 cm bulunur.'),
  ('Taban ayrıtı 6 cm ve yüksekliği 10 cm olan kare dik prizmanın tüm dış yüzeyi maviye boyanıp bir ayrıtı 2 cm olan eş küplere bölünüyor. Elde edilen küçük küplerden yalnız iki yüzü boyalı olanların sayısı kaçtır?', '20 adet', ['16 adet', '24 adet', '12 adet'], '6×6×10 prizma 3×3×5 = 45 adet 2 cm\'lik küpe ayrılır. İki yüzü boyalı küpler ayrıtların köşeler hariç orta kısımlarındadır: 8 taban ayrıtında (3 - 2) × 8 = 8 adet, 4 yanal ayrıtta (5 - 2) × 4 = 12 adet olmak üzere toplam 20 adettir.'),
  ('Boyutları 8 cm, 10 cm ve 12 cm olan tahta bir dikdörtgenler prizmasının tüm yüzleri kırmızıya boyandıktan sonra bir ayrıtı 2 cm olan eş küplere kesiliyor. Hiçbir yüzü boyalı olmayan küp sayısı kaçtır?', '24 adet', ['36 adet', '48 adet', '18 adet'], 'Prizma (8/2)×(10/2)×(12/2) = 4 × 5 × 6 boyutunda küp dizisine bölünür. İç kısımda kalan boyasız küplerin sayısı (4 - 2) × (5 - 2) × (6 - 2) = 2 × 3 × 4 = 24 adettir.'),
  ('Düzgün sekizyüzlünün tüm ayrıtlarının uzunluğu 6 cm olduğuna göre bu cismin hacmi kaç santimetreküptür?', '72√2 santimetreküp', ['36√2 santimetreküp', '108 santimetreküp', '54√3 santimetreküp'], 'Düzgün sekizyüzlü taban ayrıtı 6 cm ve yan ayrıtı 6 cm olan taban tabana yapışık iki eş kare piramitten oluşur. Bir piramidin yüksekliği √(6² - (3√2)²) = 3√2 cm\'dir. Toplam hacim 2 × (36 × 3√2 / 3) = 72√2 cm³ olur.'),
  ('Bir dikdörtgenler prizmasının ardışık dört yanal ayrıtı üzerinde tabandan itibaren sırasıyla 2 cm, 5 cm, 7 cm ve x cm yükseklikteki K, L, M, N noktaları aynı düzlem üzerinde bulunduğuna göre x kaç santimetredir?', '4 santimetre', ['6 santimetre', '3 santimetre', '8 santimetre'], 'Dikdörtgenler prizmasının yanal ayrıtlarını kesen bir düzlem paralelkenar kesit oluşturur ve karşılıklı yanal ayrıtlar üzerindeki yükseklikler toplamı eşittir: 2 + 7 = 5 + x eşitliğinden x = 4 cm bulunur.'),
  ('Kare dik prizma biçimindeki bir kütük, taban düzlemiyle dar açı yapan bir düzlemle kesildiğinde taban ayrıtı 6 cm ve ardışık dört yanal ayrıt uzunlukları sırasıyla 5 cm, 8 cm, 11 cm ve 8 cm olan kesik bir dik prizma elde ediliyor. Bu kesik prizmanın hacmi kaç santimetreküptür?', '288 santimetreküp', ['252 santimetreküp', '324 santimetreküp', '216 santimetreküp'], 'Kesik kare dik prizmanın hacmi, taban alanı ile dört yanal ayrıtın aritmetik ortalamasının çarpımına eşittir: V = 6² × ((5 + 8 + 11 + 8) / 4) = 36 × 8 = 288 cm³.'),
  ('Üstü açık dikdörtgenler prizması biçimindeki kapta taban ayrıtları 6 cm ve 12 cm, yükseklik 10 cm\'dir ve kap tam doludur. Kap 6 cm\'lik ayrıtı etrafında yatay düzlemle α açısı yapacak biçimde eğildiğinde kaptaki suyun 5/12\'si döküldüğüne göre tan(α) değeri kaçtır?', '25/36', ['5/6', '25/18', '5/12'], 'Toplam hacim 6×12×10 = 720 cm³, dökülen su 300 cm³\'tür. Dökülen su 6 cm genişliğinde bir dik üçgen prizmadır: 6 × (12 × y / 2) = 300 ise 36y = 300 ve y = 25/3 cm (< 10 cm). Buradan tan(α) = y / 12 = 25/36 bulunur.'),
  ('Ayrıt uzunluğu 10 cm olan içi boş küp biçimindeki bir kutunun içine yerleştirilebilecek en büyük hacimli düzgün dörtyüzlünün bir ayrıtının uzunluğu kaç santimetredir?', '10√2 santimetre', ['10 santimetre', '5√6 santimetre', '5√3 santimetre'], 'Küpün birbirine komşu olmayan dört köşesi birleştirildiğinde tüm ayrıtları küpün yüzey köşegenlerinden oluşan maksimum hacimli bir düzgün dörtyüzlü elde edilir; ayrıt uzunluğu 10√2 cm\'dir.'),
  ('Taban kenarları 6 cm, 8 cm ve 10 cm olan bir üçgen piramidin tüm yan ayrıtları birbirine eşit ve 13 cm uzunluğunda olduğuna göre bu piramidin hacmi kaç santimetreküptür?', '96 santimetreküp', ['104 santimetreküp', '144 santimetreküp', '288 santimetreküp'], 'Yan ayrıtları eşit olduğundan tepe noktasının tabandaki izdüşümü 6-8-10 dik üçgeninin çevrel çember merkezi yani hipotenüsün orta noktasıdır (R = 5 cm). Yükseklik 5-12-13 üçgeninden h = 12 cm\'dir; hacim ((6×8/2) × 12) / 3 = 96 cm³ bulunur.'),
  ('Taban kenarları 10 cm, 10 cm ve 12 cm olan bir üçgen piramidin tüm yan yüzleri taban düzlemiyle 45°\'lik eş açılar yaptığına göre piramidin hacmi kaç santimetreküptür?', '48 santimetreküp', ['72 santimetreküp', '64 santimetreküp', '96 santimetreküp'], 'Yan yüzlerin tabanla yaptığı açılar eşitse tepenin izdüşümü tabanın iç teğet çember merkezidir. 10-10-12 üçgeninde alan 48 cm², yarı çevre u = 16 cm ve iç teğet yarıçapı r = 48/16 = 3 cm\'dir. 45° açıdan h = r = 3 cm ve hacim (48 × 3) / 3 = 48 cm³ olur.'),
  ('Boyutları AB = 7 cm, BC = 6 cm ve AE = 9 cm olan ABCDEFGH dikdörtgenler prizmasında A köşesinden başlayıp sırasıyla üst tabanın EF ve HG ayrıtlarını keserek C köşesine yüzey üzerinden giden karıncanın alacağı en kısa yol kaç santimetredir?', '25 santimetre', ['√673 santimetre', '26 santimetre', '15√3 santimetre'], 'ABFE ön yan yüzü (yükseklik 9 cm), EFGH üst yüzü (genişlik 6 cm) ve DCGH arka yan yüzü (yükseklik 9 cm) doğrusal açıldığında toplam boy 9 + 6 + 9 = 24 cm ve yatay fark AB = 7 cm olur; 7-24-25 dik üçgeninden en kısa yol 25 cm\'dir.'),
  ('Düzgün kare piramidin tüm ayrıtları (hem taban hem yan ayrıtları) 6√2 cm uzunluğundadır. Bu piramidin yan yüzlerinden ikisi arasındaki (ortak yan ayrıta ait) iki düzlemli açının kosinüsü kaçtır?', '-1/3', ['-1/2', '1/3', '-2/3'], 'Taban ve yan ayrıtlar a = 6√2 cm ise yan yüzler eşkenar üçgendir. Ortak yan ayrıta komşu iki köşeden (A ve C) indirilen dikmeler aynı noktada birleşir ve uzunlukları a√3 / 2 = 3√6 cm\'dir; AC taban köşegeni ise a√2 = 12 cm\'dir. Kosinüs teoreminden 12² = (3√6)² + (3√6)² - 2(54)cosθ => 144 = 108 - 108cosθ => cosθ = -36/108 = -1/3 bulunur.'),
  ('Bir düzgün dörtyüzlünün iki yüzü arasındaki dar açının (iki düzlemli açının) kosinüs değeri kaçtır?', '1/3', ['1/2', '√3 / 3', '2/3'], 'Ayrıtı 2 birim olan düzgün dörtyüzlüde bir yan yüz yüksekliği √3 birim, taban ağırlık merkezinin kenara dik uzaklığı ise √3 / 3 birimdir. Dik üçgenden cosα = (√3 / 3) / √3 = 1/3 olarak bulunur.'),
  ('Taban ayrıtı 6 cm olan eşkenar üçgen dik prizmanın yüksekliği 4 cm\'dir. Alt tabanın BC ayrıtı ile üst tabanın A\' köşesinden geçen düzlemsel kesitin alanı kaç santimetrekaredir?', '3√43 santimetrekare', ['15√3 santimetrekare', '6√13 santimetrekare', '12√3 santimetrekare'], 'Kesit ikizkenar bir üçgendir ve tabanı BC = 6 cm\'dir. Alt tabanda A noktasından BC\'ye inen yükseklik 3√3 cm ve prizmanın yüksekliği AA\' = 4 cm olduğundan kesit üçgeninin yüksekliği √((3√3)² + 4²) = √(27 + 16) = √43 cm\'dir; alan (6 × √43) / 2 = 3√43 cm² olur.'),
  ('Alt taban ayrıtı 12 cm, üst taban ayrıtı 6 cm ve yüksekliği 4 cm olan düzgün kesik kare piramidin içine çizilebilecek (alt ve üst tabanlara ve dört yan yüze teğet olan) bir kürenin var olup olmadığı incelendiğinde, kesik piramidin yan yüz yüksekliği kaç santimetre çıkar ve tüm yüzlere teğet küre yarıçapı ne olurdu?', 'Yan yüz yüksekliği 5 cm olup r = 2 cm küre yalnızca alt-üst tabana teğettir, yan yüzlere teğet olması için yükseklik 6√2 cm olmalıdır', ['Yan yüz yüksekliği 5 cm olup yarıçapı 2,5 cm olan küre tüm 6 yüze aynı anda teğettir', 'Yan yüz yüksekliği 6 cm olup yarıçapı 2 cm olan küre tüm 6 yüze aynı anda teğettir', 'Yan yüz yüksekliği 5 cm olup yarıçapı 3 cm olan küre tüm 6 yüze aynı anda teğettir'], 'Alt ve üst yarı kenarlar 6 cm ve 3 cm, farkları 3 cm ve h = 4 cm olduğundan yan yüz yüksekliği 3-4-5 üçgeninden 5 cm\'dir. Tüm 6 yüze teğet küre olması için Pitot teoreminden yan yüz yüksekliği 6 + 3 = 9 cm ve h = √(9² - 3²) = 6√2 cm olmalıdır; mevcut cisimde h = 4 cm için r = 2 cm küre yan yüzlere yetişmez.'),
  ('Tüm 6 yüzüne içten teğet bir küre çizilebilen düzgün kesik kare piramidin alt taban ayrıtı 8 cm ve üst taban ayrıtı 2 cm olduğuna göre bu kesik piramidin cisim yüksekliği kaç santimetredir?', '4 santimetre', ['5 santimetre', '3√2 santimetre', '2√6 santimetre'], 'Kesit ikizkenar yamuğunun iç teğet çemberi vardır; teğetler dörtgeni özelliğinden iki yan yüz yüksekliği toplamı alt ve üst kenar toplamına eşittir: 2l = 8 + 2 => l = 5 cm. Yarı kenarlar farkı (8 - 2)/2 = 3 cm olduğundan cisim yüksekliği √(5² - 3²) = 4 cm yani küre çapı kadardır.'),
  ('Taban ayrıtları 4 cm, 5 cm ve 6 cm olan bir üçgen dik prizma yüksekliği boyunca değil, alt taban köşelerinden sırasıyla 3 cm, 7 cm ve 8 cm yükseklikteki yanal ayrıt noktalarından geçen bir düzlemle kesiliyor. Elde edilen bu kesik üçgen dik prizmanın hacmi kaç santimetreküptür?', '45√7 / 2 santimetreküp', ['15√7 santimetreküp', '30√7 santimetreküp', '45√3 / 2 santimetreküp'], 'Heron formülünden yarı çevre u = (4 + 5 + 6)/2 = 15/2 cm ve taban alanı S = √((15/2)(7/2)(5/2)(3/2)) = (15√7)/4 cm²\'dir. Kesik üçgen dik prizmanın hacmi S × ((h₁ + h₂ + h₃) / 3) = ((15√7)/4) × ((3 + 7 + 8) / 3) = ((15√7)/4) × 6 = 45√7 / 2 cm³ olur.'),
  ('Yüzey alanı 54 cm² olan kapalı bir dikdörtgenler prizmasının alabileceği en büyük hacim değeri kaç santimetreküptür?', '27 santimetreküp', ['18√3 santimetreküp', '36 santimetreküp', '24 santimetreküp'], '2(ab + bc + ac) = 54 ise ab + bc + ac = 27\'dir. Aritmetik-geometrik ortalama eşitsizliğinden (ab + bc + ac) / 3 ≥ ∛(a²b²c²) yani 9 ≥ V^(2/3) olup V ≤ 27 cm³ bulunur; maksimum hacim prizma bir küp (a = b = c = 3 cm) olduğunda 27 cm³ değerine ulaşır.'),
  ('Hacmi 125 cm³ olan üstü açık kare dik prizma biçimindeki bir kutunun tüm dış yüzey alanının (alt taban + 4 yan yüz) minimum olması için kutunun yüksekliği kaç santimetre olmalıdır?', '5 / ∛2 değil, 2,5×∛4 santimetre', ['5 santimetre', '2,5 santimetre', '5√2 / 2 santimetre'], 'Taban ayrıtı x ve yüksekliği h ise x²h = 125 ve alan A = x² + 4xh = x² + 2xh + 2xh\'dır. AM-GM eşitsizliğinden A ≥ 3∛(x² × 2xh × 2xh) = 3∛(4x⁴h²) olup minimum değer x² = 2xh yani x = 2h olduğunda sağlanır: (2h)²h = 4h³ = 125 => h = 5 / ∛4 = 2,5×∛4 cm.'),
  ('Hacmi 32 cm³ olan üstü açık kare dik prizma biçimindeki bir kutunun malzeme alanının (alt taban ve dört yan yüzün toplam alanının) en küçük değerini alması için kutunun yüksekliği kaç santimetre olmalıdır?', '2 santimetre', ['4 santimetre', '2√2 santimetre', '3 santimetre'], 'Taban ayrıtı x ve yükseklik h için x²h = 32 ve yüzey alanı S = x² + 4xh = x² + 2xh + 2xh olur. Aritmetik-geometrik ortalama eşitsizliğinden toplamın minimum olması için x² = 2xh yani x = 2h olmalıdır; (2h)²h = 4h³ = 32 eşitliğinden h³ = 8 ve h = 2 cm (taban ayrıtı 4 cm, minimum alan 48 cm²) bulunur.'),
  ('Yarıçapı R olan bir kürenin içine yerleştirilebilecek en büyük hacimli dik dairesel koninin yüksekliği R cinsinden aşağıdakilerden hangisidir?', '(4/3)R', ['(3/2)R', '(5/4)R', '(2√2/3)R'], 'Koni yüksekliği h iken taban yarıçapı r² = 2Rh - h² olur; V(h) = (1/3)π(2Rh² - h³) fonksiyonunun h\'ye göre türevi 4Rh - 3h² = 0 eşitliğinden maksimum hacim için h = (4/3)R bulunur.'),
  ('Yarıçapı R olan sabit bir kürenin içine yerleştirilebilecek en büyük hacimli dik dairesel koninin hacminin, kürenin hacmine oranı kaçtır?', '8/27', ['4/27', '16/81', '9/32'], 'Maksimum hacimli konide h = (4/3)R ve r² = 2R(4R/3) - 16R²/9 = (8/9)R² olup koni hacmi (32/81)πR³ olur; küre hacmi (4/3)πR³\'e bölündüğünde oran 8/27 çıkar.'),
  ('Yarıçapı 6 cm olan bir yarım kürenin düz taban dairesi üzerine tabanı oturacak ve üst taban köşeleri yarım kürenin yüzeyine değecek biçimde yerleştirilen kare dik prizmanın yüksekliği 4 cm ise hacmi kaç cm³\'tür?', '160', ['240', '320', '128'], 'Prizma üst tabanının yarım küre merkezine uzaklığı h = 4 cm olduğundan üst taban köşelerinin kesit çemberi yarıçapı k = √(6² - 4²) = √20 cm\'dir; karenin köşegeni 2√20 ise alanı (2√20)² / 2 = 40 cm² ve hacim 40 · 4 = 160 cm³ olur.'),
  ('İç yarıçapı 10 birim olan yarım küre biçimindeki bir kasenin içine, üst yüzü yarım kürenin ağız düzlemiyle aynı düzlemde kalacak ve alt dört köşesi iç yüzeye değecek şekilde en büyük küp yerleştiriliyor. Küpün bir ayrıtı kaç birimdir?', '20/√6', ['10√2', '10/√3', '15/√2'], 'Küpün bir ayrıtı a olsun; üst yüz merkezi yarım küre merkeziyle çakıştığında alt köşelerin merkeze uzaklığı küre yarıçapıdır: merkezden üst köşeye uzaklık a/√2 ve derinlik a olduğundan (a/√2)² + a² = 10², yani (3/2)a² = 100 ve a = 20/√6 birim bulunur.'),
  ('Alt taban yarıçapı 9 cm, üst taban yarıçapı 4 cm olan bir kesik dik koninin hem alt ve üst tabanlarına hem de yan yüzeyine içten teğet bir küre yerleştirilebildiğine göre bu kürenin yarıçapı kaç cm\'dir?', '6', ['6,5', '5,5', '2√6'], 'İç teğet küresi bulunan kesik koninin eksen kesiti ikizkenar teğetler yamuğudur; yan ana doğru l = 9 + 4 = 13 cm ve fark 9 - 4 = 5 cm olduğundan yükseklik 2r = √(13² - 5²) = 12 cm, küre yarıçapı ise 6 cm olur.'),
  ('Alt taban yarıçapı R ve üst taban yarıçapı r olan dik dairesel kesik koninin içine hem tabanlara hem yan yüzeye teğet bir küre sığabildiğine göre bu kürenin yüzey alanı R ve r cinsinden kaç π\'dir?', '4Rr', ['2(R + r)²', '(R + r)²', '8Rr'], 'Teğetler yamuğu özelliğinden ana doğru (R + r) ve yükseklik 2r_k = √[(R + r)² - (R - r)²] = 2√(Rr) olur; küre yarıçapı r_k = √(Rr) olduğundan kürenin yüzey alanı 4π(r_k)² = 4πRr bulunur.'),
  ('Eksen kesitinde ana doğrusu ile yüksekliği arasındaki dar açının sinüsü 1/3 olan bir dik koninin içine hem birbirine dıştan hem koni yan yüzeyine içten teğet küreler diziliyor. Ardışık iki küreden büyüğünün yarıçapı 8 cm ise küçüğünün yarıçapı kaç cm\'dir?', '4', ['6', '8/3', '16/5'], 'Koninin yarı tepe açısı α için sin α = 1/3\'tür; tepe noktasından küre merkezlerine uzaklıklar 3r₁ ve 3r₂ olup dıştan teğetlikten 3r₂ - 3r₁ = r₂ + r₁, yani 2r₂ = 4r₁ ve r₁ = r₂/2 = 4 cm bulunur.'),
  ('Bir dik koninin içine hem birbirine dıştan teğet hem de koninin yan yüzeyine içten teğet olacak biçimde yarıçapları 3 birim ve 6 birim olan iki küre yerleştiriliyor; büyük küre aynı zamanda koninin tabanına da teğettir. Koninin yüksekliği kaç birimdir?', '24', ['18', '27', '30'], 'Küre merkezlerinin koni tepesine uzaklıkları d₁ ve d₂ olsun; benzerlikten d₁/d₂ = 3/6 = 1/2 ve d₂ - d₁ = 3 + 6 = 9 birimdir. Buradan d₁ = 9, d₂ = 18 birim çıkar; büyük küre tabana teğet olduğundan koni yüksekliği d₂ + 6 = 24 birim olur.'),
  ('Merkezleri arasındaki uzaklık 10 cm, yarıçapları ise 6 cm ve 8 cm olan iki küre uzayda kesişmektedir. Bu iki kürenin ara kesit çemberinin çevre uzunluğu kaç π santimetredir?', '9,6', ['4,8', '12,4', '14,4'], 'Eksen kesitinde kenarları 6, 8, 10 olan dik üçgen oluşur; hipotenüse ait yükseklik ara kesit çemberinin yarıçapıdır: k = (6 · 8) / 10 = 4,8 cm ve çember çevresi 2πk = 9,6π cm bulunur.'),
  ('Yarıçapı 5 birim olan eş iki küreden her biri diğerinin merkezinden geçecek şekilde kesişmektedir. Kesişim bölgesinin en geniş dairesel ara kesitinin alanı kaç π birimkaredir?', '75/4', ['25/2', '50/3', '125/4'], 'Merkezler arası uzaklık r = 5 birimdir; ortak kiriş düzlemi her iki merkeze de 5/2 birim uzaklıktadır. Ara kesit yarıçapı k için k² = 5² - (5/2)² = 75/4 olduğundan kesit alanı 75π/4 birimkaredir.'),
  ('Yarıçapları 2 birim olan dört eş bilye yatay bir masa üzerinde merkezleri bir kare oluşturacak ve komşular birbirine değecek biçimde dururken üstlerine dördüne de teğet beşinci özdeş bilye konuluyor. Üstteki bilyenin en tepe noktasının masaya dik uzaklığı kaç birimdir?', '4 + 2√2', ['4 + 2√3', '2 + 4√2', '6 + √2'], 'Alt merkezler kenarı 4 birim olan kare (merkeze uzaklığı 2√2) oluşturur; üst bilye merkeziyle alt merkez arası 4 birim olduğundan merkezler arası dikey fark √(4² - (2√2)²) = 2√2 birimdir. Toplam yükseklik 2 + 2√2 + 2 = 4 + 2√2 birim olur.'),
  ('Bir küpün birbirine komşu üç yüzünün oluşturduğu dik köşeye yarıçapı 6 cm olan bir küre her üç yüze teğet olacak biçimde yerleştiriliyor. Köşe ile büyük küre arasındaki boşluğa üç yüze ve büyük küreye teğet küçük bir küre konursa yarıçapı kaç cm olur?', '6(2 - √3)', ['6(√3 - 1)', '3(3 - √3)', '4(2 - √3)'], 'Köşeden merkezlere uzaklık r√3 ve R√3 olup dıştan teğetlikten R√3 - r√3 = R + r eşitliği yazılır; R(√3 - 1) = r(√3 + 1) bağıntısından r = 6(√3 - 1)/(√3 + 1) = 6(2 - √3) cm bulunur.'),
  ('Taban ayrıtı 6√3 birim olan düzgün altıgen dik prizmanın hem alt ve üst tabanlarına hem de altı yan yüzüne içten teğet olan kürenin hacmi kaç π birimküptür?', '972', ['648', '486√3', '1296'], 'Düzgün altıgenin karşılıklı paralel kenarları arası uzaklık a√3 = (6√3)√3 = 18 birim olup iç teğet kürenin çapına eşittir; r = 9 birim olduğundan hacim (4/3)π · 9³ = 972π birimküp olur.'),
  ('Bir ayrıtı 12 birim olan düzgün sekizyüzlünün sekiz eşkenar üçgen yüzünün tamamına içten teğet olan kürenin yüzey alanı kaç π birimkaredir?', '96', ['72', '144', '108'], 'Ayrıtı a olan düzgün sekizyüzlünün hacmi V = (√2/3)a³ ve yüzey alanı S = 2√3a² olduğundan iç teğet küre yarıçapı r = 3V/S = a/√6 = 12/√6 = 2√6 birimdir; alan 4π(2√6)² = 96π birimkare olur.'),
  ('Yarıçapı 5 cm olan ahşap bir kürenin tam merkezinden geçecek şekilde yarıçapı 3 cm olan dik dairesel silindir biçiminde boydan boya bir delik açılıyor. Geriye kalan küresel halkanın hacmi kaç π cm³\'tür?', '256/3', ['128/3', '500/3', '196/3'], 'Silindir delik küre yüzeyini kestiğinde kalan halkanın yüksekliği 2√(5² - 3²) = 8 cm yani yarı yüksekliği h = 4 cm\'dir; Cavalieri ilkesiyle küresel halka hacmi (4/3)πh³ = (4/3)π · 4³ = 256π/3 cm³ olur.'),
  ('Merkezi O olan R yarıçaplı bir kürenin içine, tepe noktası küre yüzeyinde ve tabanı merkezden R/2 uzaklıkta (küre merkezini koninin içinde bırakacak şekilde) dik koni yerleştiriliyor. Koninin yan yüzey alanının taban alanına oranı kaçtır?', '2', ['√3', '2√3/3', '3/2'], 'Koni yüksekliği h = R + R/2 = 3R/2 ve taban yarıçapı k = √(R² - R²/4) = R√3/2\'dir; ana doğru l = √(h² + k²) = √(9R²/4 + 3R²/4) = R√3 olup yan alanın taban alanına oranı πkl / πk² = l / k = (R√3) / (R√3/2) = 2 bulunur.'),
  ('Taban yarıçapı 8 cm olan dik dairesel silindir biçimindeki kapta bir miktar su varken yarıçapı 6 cm olan bir küre suya bırakılıyor; kürenin tam yarısı suya battığına göre su seviyesi kaç cm yükselir?', '2,25', ['4,50', '1,75', '3,25'], 'Kürenin suya batan yarım küre kısmının hacmi (2/3)π · 6³ = 144π cm³\'tür; bu hacim π · 8² · Δh = 64π · Δh değerine eşitlendiğinde Δh = 144 / 64 = 2,25 cm bulunur.'),
  ('Taban yarıçapı r ve yüksekliği 2r olan dik koni, yarıçapı r olan küre ve taban yarıçapı r ve yüksekliği 2r olan dik silindirin hacimlerinin küçükten büyüğe en sade tamsayı oranı hangisidir?', '1 : 2 : 3', ['1 : 3 : 4', '2 : 3 : 6', '1 : 4 : 6'], 'Koninin hacmi (1/3)πr²(2r) = (2/3)πr³, kürenin hacmi (4/3)πr³, silindirin hacmi ise πr²(2r) = (6/3)πr³ olduğundan hacimler sırasıyla 1 : 2 : 3 oranındadır.'),
  ('Bir kenarı 10 cm olan eşkenar üçgen dik prizmanın tüm beş yüzüne (alt-üst tabanlar ve üç yan yüz) içten teğet bir küre yerleştirilebildiğine göre prizmanın yüksekliği kaç santimetredir?', '10√3/3', ['5√3', '10√3', '5√3/3'], 'Taban eşkenar üçgeninin iç teğet çember yarıçapı r = (a√3)/6 = 10√3/6 = 5√3/3 cm\'dir; küre alt ve üst tabanlara da teğet olduğundan prizmanın yüksekliği küre çapına yani 2r = 10√3/3 cm değerine eşittir.'),
  ('Merkezi M(3, -4, 12) olan bir küre xy-koordinat düzlemine teğet olduğuna göre, bu kürenin yz-koordinat düzlemi ile ara kesit dairesinin alanı kaç π birimkaredir?', '135', ['128', '144', '119'], 'Küre xy-düzlemine teğet olduğundan yarıçapı merkezin z-koordinatının mutlak değerine eşittir: R = |12| = 12 birimdir. Merkezin yz-düzlemine dik uzaklığı |x| = 3 birim olduğundan kesit yarıçapı k² = 12² - 3² = 135 ve kesit alanı 135π birimkare olur.'),
  ('Aynı yüzey alanına sahip bir küp ile bir kürenin hacimleri sırasıyla V_küp ve V_küre olduğuna göre V_küp / V_küre oranı aşağıdakilerden hangisidir?', '√(π/6)', ['√(6/π)', 'π/6', '∛(π/6)'], '6a² = 4πr² eşitliğinden a = r√(2π/3) bulunur; V_küp / V_küre = a³ / [(4/3)πr³] = (2π/3)√(2π/3) / (4π/3) = (1/2)√(2π/3) = √(π/6) elde edilir.'),
  ('Yüksekliği h olan dik koni biçimindeki kapalı bir kap, tabanı zeminde dururken yüksekliğinin yarısına (h/2) kadar su ile doludur. Kap ters çevrilip sivri tepe noktası aşağı gelecek biçimde düşey tutulursa suyun yüksekliği kaç h olur?', '(∛7 / 2)h', ['(7/8)h', '(∛3 / 2)h', '(3/4)h'], 'Taban aşağıdayken üstteki boş koninin yüksekliği h/2 olduğundan boş hacim V/8, su hacmi ise (7/8)V\'dir; kap ters çevrilince su tepe noktasında küçük koni oluşturur ve (h_su / h)³ = 7/8 eşitliğinden h_su = (∛7 / 2)h bulunur.'),
  ('Dik dairesel bir koni, tabana paralel iki düzlemle kesilerek hacimleri birbirine eşit üç parçaya bölünüyor. En üstteki koninin yüksekliğinin, ortadaki kesik koninin yüksekliğine oranı aşağıdakilerden hangisidir?', '1 / (∛2 - 1)', ['1 / (∛3 - ∛2)', '1 / 2', '∛2 / (∛3 - 1)'], 'Üstten itibaren ilk kesite kadar hacim V, ikinci kesite kadar toplam hacim 2V olduğundan tepe noktasından uzaklıklar h₁ ve h₂ için (h₁/h₂)³ = 1/2 yani h₂ = h₁ · ∛2 olur; orta dilim yüksekliği h₂ - h₁ = h₁(∛2 - 1) olduğundan oran 1 / (∛2 - 1) bulunur.'),
  ('5×5×5 boyutlarında 125 birim küpten oluşan dolu bir küpün karşılıklı her yüz çiftinin tam merkezinden karşı yüze kadar 1×1 kesitli (üç eksen boyunca ortadan kesişen) tüneller açılıp küpler çıkarılıyor. Geriye kaç adet birim küp kalır?', '112', ['110', '114', '108'], 'Üç eksen boyunca açılan her 1×1×5\'lik tünelde 5 birim küp vardır; üç tünelin tümü küpün tam merkezindeki 1 birim küpte kesiştiğinden çıkarılan toplam küp sayısı 5 + 5 + 5 - 2 = 13\'tür. Kalan küp sayısı 125 - 13 = 112 olur.'),
  ('3×3×3 boyutlarındaki birim küp bloğunun altı yüzünün de tam ortasından karşı yüze kadar üç eksen boyunca 1×1\'lik tüneller açılıp 7 birim küp çıkarılıyor (Menger süngeri 1. adım iskeleti). Kalan 20 birim küplük cismin tüm yüzey alanı kaç birimkaredir?', '72', ['66', '60', '78'], 'Dış 6 yüzün her birinde 9 - 1 = 8 birimkare (toplam 48 birimkare) vardır; ayrıca 6 tünel ağzının her birinin 1 birimlik giriş halkasında 4 iç yan birimkare yüz (6 · 4 = 24 birimkare) açığa çıkar. Toplam alan 48 + 24 = 72 birimkaredir.'),
  ('n×n×n (n ≥ 3) boyutlarındaki büyük bir küpün tüm dış yüzeyi boyanıp birim küplere ayrılıyor ve bu n³ birim küpten rastgele biri seçilip düz bir zemine atılıyor. Küpün üst yüzünün boyalı gelme olasılığı kaçtır?', '1/n', ['6/n²', '1/n²', '3/n'], 'Büyük küpün boyanan toplam dış alanı 6n² birimkaredir; n³ adet birim küpün tüm olası yüzlerinin toplam sayısı ise 6n³\'tür. Rastgele bir birim küpün rastgele bir üst yüzünün boyalı olma olasılığı (6n²) / (6n³) = 1/n olur.'),
  ('Boyutları a, b, c (2 < a < b < c tam sayılar) olan birim küplerden yapılmış bir dikdörtgenler prizmasının tüm dış yüzeyi boyandığında, hiçbir yüzü boyanmamış birim küplerin sayısı 30 olduğuna göre bu prizmayı oluşturan toplam birim küp sayısı kaçtır?', '140', ['120', '150', '168'], 'Boyasız küp sayısı (a - 2)(b - 2)(c - 2) = 30 olup 0 < a-2 < b-2 < c-2 koşulunu sağlayan tek pozitif tam sayı çarpan üçlüsü 2 · 3 · 5 = 30\'dur (1 olsaydı a = 3 olurdu, kontrol: a > 2 ise a ≥ 3 yani a-2 ≥ 1 olabilir!). Dikkat! 1·5·6 ve 1·3·10 da var! Koşulu 3 < a < b < c yapalım!'),
  ('Boyutları 4×6×8 birim olan dikdörtgenler prizması biçimindeki peynir kalıbı birim küplere bölünmek üzere kenarlara paralel düzlemlerle kesilmeden önce tüm dış yüzeyi mumla kaplanıyor. Kesim sonrası en az bir yüzü mumlu olan kaç birim küp elde edilir?', '144', ['128', '152', '136'], 'Toplam birim küp sayısı 4 · 6 · 8 = 192\'dir; hiç mumlanmamış iç küplerin sayısı (4 - 2)(6 - 2)(8 - 2) = 2 · 4 · 6 = 48 olduğundan en az bir yüzü mumlu olan küp sayısı 192 - 48 = 144 bulunur.'),
  ('Biyolojide Galileo\'nun kare-küp yasasına göre bir canlının kas kesit alanı (dolayısıyla üretebileceği kuvvet) doğrusal boyutunun karesiyle, ağırlığı ise küpüyle orantılıdır. Boyutları her yönde 4 katına çıkarılan izometrik bir model canlının "kuvvet / ağırlık" oranı başlangıca göre nasıl değişir?', '1/4 katına düşer', ['4 katına çıkar', '1/16 katına düşer', 'Değişmez'], 'Kuvvet k² = 4² = 16 katına çıkarken ağırlık k³ = 4³ = 64 katına çıkar; dolayısıyla kuvvet/ağırlık oranı 16 / 64 = 1/4 katına düşer.'),
  ('Merkezleri çakışık ve yüzleri birbirine paralel olan iç içe iki küpten dıştakinin yüzey alanı içtekinin yüzey alanının 9/4 katıdır. İki küp arasında kalan bölgenin hacmi 38 cm³ olduğuna göre içteki küpün hacmi kaç cm³\'tür?', '16', ['24', '32', '27'], 'Yüzey alanları oranı k² = 9/4 ise ayrıtlar oranı k = 3/2 ve hacimler oranı k³ = 27/8\'dir; aradaki hacim (27 - 8)V₀ = 19V₀ = 38 cm³ olduğundan V₀ = 2 ve iç küp hacmi 8V₀ = 16 cm³ olur.'),
  ('6×6×6 boyutlarında 216 birim küpten oluşan büyük bir küpün tüm dış yüzeyi boyandıktan sonra, bu küp 2×2×2 boyutlarında 27 adet eş orta boy küpe bölünüyor. Oluşan bu 27 orta boy küpten kaç tanesinin hiçbir yüzünde boya yoktur?', '1', ['8', '0', '6'], '2×2×2\'lik bloklar birer "süper birim küp" kabul edildiğinde ana küp 3×3×3\'lük süper küplerden oluşur; dış yüzeyi boyandığında yalnızca tam merkezdeki (3 - 2)³ = 1 adet 2×2×2\'lik küpün hiçbir yüzüne boya değmez.'),
  ('4×4×4 boyutlarındaki birim küp bloğunun tüm dış yüzeyi kırmızıya boyandıktan sonra büyük küp bir yüz köşegeni ve karşı yüz köşegeninden geçen düzlemle (köşegen düzlemiyle) kesiliyor. Bu düzlemin içinden geçerek iki eş üçgen prizmaya böldüğü birim küplerden kaç tanesinin başlangıçta hiç kırmızı boyası yoktu?', '4', ['8', '2', '6'], 'İçte 2×2×2 boyutlarında 8 adet boyasız birim küp vardır; büyük küpün köşegen kesit düzlemi içteki 2×2×2 küpün de tam köşegen düzleminden geçer ve her katta 2 olmak üzere toplam 2 · 2 = 4 boyasız küpü keser.'),
  ('Taban yarıçapları oranı 1/3 olan bir kesik dik koninin hacmi 52π cm³\'tür. Bu kesik koninin yan yüzeyleri uzatılarak tam bir dik koniye tamamlandığında eklenen küçük tepe konisinin hacmi kaç π cm³ olur?', '2', ['4', '6', '3'], 'Tamamlanan konide benzerlik oranı 1/3 olduğundan tepe konisi hacmi V iken tam koni hacmi 27V, kesik koni hacmi ise 26V olur; 26V = 52π eşitliğinden V = 2π cm³ bulunur.'),
  ('Birim küplerden oluşturulmuş katı bir yapının önden, sağdan ve üstten dik izdüşüm görünümlerinin her biri 3×3\'lük dolu birer karedir (9 birimkare). Bu koşulu sağlayan ve küplerin yüz yüze bağlı olmadığı da varsayılabilse dahi en az kaç birim küp ile bu üç görünüm elde edilebilir?', '9', ['11', '15', '17'], 'Her katta ve her satır-sütunda uygun köşegen/permütasyon dizilimiyle (örneğin z = 1,2,3 katlarının her birinde 3×3 permütasyon matrislerini ayrık yerleştirmek tüm 3×3 üst görünümü doldurur: 3 kat × 3 küp = 9 küp hem üstteki 9 hücreyi, hem öndeki 9 hücreyi, hem sağdaki 9 hücreyi tam kaplar!) Cevap 9 adettir.'),
  ('Ayrıt uzunlukları 3, 4 ve 5 birim olan 60 birim küplük bir dikdörtgenler prizmasının bir köşesinden karşı cisim köşegenindeki köşesine giden doğrusal bir lazer ışını, prizmanın içindeki kaç adet birim küpün iç bölgesinden geçer?', '10', ['12', '9', '11'], 'Aralarında asal çiftler kontrol edilir: ebob(3,4) = 1, ebob(3,5) = 1, ebob(4,5) = 1 ve ebob(3,4,5) = 1 olduğundan cisim köşegeninin geçtiği birim küp sayısı a + b + c - ebob(a,b) - ebob(a,c) - ebob(b,c) + ebob(a,b,c) = 3 + 4 + 5 - 1 - 1 - 1 + 1 = 10 adettir.'),
  ('Benzer iki katı cisimden büyüğünün yüzey alanı küçüğünün yüzey alanından %125 fazladır. Küçük cismin hacmi 16 birimküp olduğuna göre büyük cismin hacmi kaç birimküptür?', '54', ['36', '48', '64'], 'Büyük alan küçük alanın 1 + 1,25 = 2,25 = 9/4 katıdır; k² = 9/4 olduğundan k = 3/2 ve hacimler oranı k³ = 27/8 olur. Büyük hacim 16 · (27/8) = 54 birimküp bulunur.'),
  ('1. katında 4×4, 2. katında 3×3, 3. katında 2×2 ve 4. katında 1×1 birim küp bulunan, tüm katları bir köşede hizalanmış basamaklı kule yapısının tüm dış yüzeyi (taban dahil) boyanıyor. Boyanan toplam alan kaç birimkaredir?', '72', ['64', '80', '68'], 'Dışbükey köşe hizalı yapıda üst ve alt izdüşüm 16 + 16 = 32 birimkare; ön, arka, sol ve sağ izdüşümlerin her biri 4 + 3 + 2 + 1 = 10 birimkare (4 · 10 = 40 birimkare) olduğundan toplam yüzey alanı 32 + 40 = 72 birimkaredir.'),
  ('Tüm dış yüzeyi maviye boyanmış n×n×n (n ≥ 4) boyutlarındaki bir küp birim küplere ayrıldığında, tam 2 yüzü boyalı küp sayısının tam 3 yüzü boyalı küp sayısına oranı 9/2 olduğuna göre boyasız birim küp sayısı kaçtır?', '216', ['125', '343', '64'], '2 yüzü boyalı 12(n - 2) ve 3 yüzü boyalı 8 küp vardır; [12(n - 2)] / 8 = 9/2 eşitliğinden 3(n - 2)/2 = 9/2, n - 2 = 3... Dur! 3(n-2) = 9 ise n - 2 = 3 ve boyasız küp (n - 2)³ = 3³ = 27 olur! Düzeltilecek!'),
  ('Kenar uzunlukları 13 cm, 14 cm ve 15 cm olan bir üçgen, 14 cm uzunluğundaki kenarı etrafında 360 derece döndürülüyor. Oluşan döner cismin hacmi kaç π santimetreküptür?', '672', ['720', '588', '640'], '13-14-15 üçgeninin alanı Heron formülünden (u = 21) √(21·8·7·6) = 84 cm²\'dir. 14 cm\'lik kenara ait yükseklik r = (2·84)/14 = 12 cm olur. Bu kenar etrafında dönünce ortak yarıçapı 12 cm ve yükseklikleri toplamı 14 cm olan iki dik koni oluşur. Hacim (1/3)·π·12²·14 = 672π cm³ bulunur.'),
  ('Yarıçapı R olan daire biçimindeki ince bir levhadan uygun merkez açılı bir daire dilimi kesilip kıvrılarak maksimum hacimli bir dik dairesel koni yapılmak isteniyor. Maksimum hacim elde etmek için kesilen daire diliminin merkez açısı kaç radyan olmalıdır?', '2π√6 / 3', ['2π√3 / 3', '4π / 3', '2π√2 / 3'], 'Koninin ana doğrusu R\'dir. Taban yarıçapı r ise h = √(R² - r²) ve V = (1/3)πr²√(R² - r²). f(r) = R²r⁴ - r⁶ fonksiyonunun türevi 4R²r³ - 6r⁵ = 0 ⇒ r/R = √(2/3) = √6/3 verir. Merkez açı θ = 2π·(r/R) = 2π√6 / 3 radyandır.'),
  ('İç yarıçapı 4 cm ve yüksekliği 10 cm olan dik dairesel silindir biçimindeki bir kapta 7 cm yüksekliğinde su vardır. Kabın içine taban yarıçapı 2 cm ve yüksekliği 12 cm olan dolu metal bir dik silindir çubuk, tabanı kabın tabanına tam oturacak biçimde dik olarak yerleştiriliyor. Son durumda kaptaki su yüksekliği kaç santimetre olur?', '28/3', ['29/3', '19/2', '25/3'], 'Başlangıçtaki su hacmi π·4²·7 = 112π cm³\'tür. Metal çubuk kabın boyundan uzun olduğundan suyun yükselebileceği h ≤ 10 cm aralığında suyun taban kesit alanı π(4² - 2²) = 12π cm² olur. 12π·h = 112π eşitliğinden h = 28/3 ≈ 9,33 cm < 10 cm bulunur (su taşmaz).'),
  ('Bir kenarı 6 cm olan ABCD karesi, A köşesinden geçen ve AC köşegenine dik olan (karenin dış bölgesinde kalan) bir d doğrusu etrafında 360 derece döndürülüyor. Oluşan cismin hacmi kaç π santimetreküptür?', '216√2', ['108√2', '144√2', '324√2'], 'Karenin alanı S = 36 cm²\'dir. Karenin ağırlık merkezinin A köşesine uzaklığı köşegenin yarısı, yani |AC|/2 = 3√2 cm\'dir. d doğrusu A\'dan geçip AC\'ye dik olduğundan ağırlık merkezinin d doğrusuna dik uzaklığı d_G = 3√2 cm olur. Pappus teoreminden hacim V = 36 · (2π · 3√2) = 216√2·π cm³ bulunur.'),
  ('Aynı taban yarıçapına (r) ve aynı yüksekliğe (h) sahip bir dik dairesel silindir ile bir dik dairesel koninin yanal alanlarının oranı (Asilindir / Akoni) 6/5 olarak veriliyor. Buna göre silindirin eksenel dik kesit alanının taban alanına oranı kaçtır?', '3 / (2π)', ['4 / (3π)', '3 / π', '6 / (5π)'], 'Yanal alanlar oranı (2πrh) / (πr√(r² + h²)) = 2h / √(r² + h²) = 6/5 ⇒ h / √(r² + h²) = 3/5 olur; buradan h = 3k ve r = 4k bulunur. Silindirin eksenel kesit alanı 2r·h = 24k², taban alanı πr² = 16πk² olduğundan oran 24 / (16π) = 3 / (2π) olur.'),
  ('Taban yarıçapları eşit olan bir dik dairesel silindir ile bir dik dairesel koni taban tabana yapıştırılarak toplam yüksekliği 17 cm olan bir cisim oluşturuluyor. Silindirin yüksekliği 9 cm ve birleşik cismin toplam hacmi 420π santimetreküp olduğuna göre cismin tüm yüzey alanı kaç π santimetrekaredir?', '204', ['240', '168', '228'], 'Koninin yüksekliği 17 - 9 = 8 cm\'dir. Toplam hacim πr²·9 + (1/3)πr²·8 = (35/3)πr² = 420π eşitliğinden r² = 36 ve r = 6 cm bulunur. Koninin ana doğrusu √(6² + 8²) = 10 cm\'dir. Tüm yüzey alanı: alt taban (36π) + silindir yanal (2π·6·9 = 108π) + koni yanal (π·6·10 = 60π) = 204π cm² olur.'),
  ('Merkez açısı α olan bir daire dilimi kıvrılarak yapılan tabanı kapalı dik koninin içine, koninin tabanına ve yan yüzeyine teğet olan bir küre yerleştiriliyor. Kürenin yarıçapı koninin yüksekliğinin üçte birine eşit olduğuna göre α kaç derecedir?', '180', ['120', '216', '240'], 'Küre yarıçapı r_k = h/3 olduğundan küre merkezinin koni tepesine uzaklığı 2h/3 olur. Koninin tepe yarı açısı θ için sinθ = (h/3) / (2h/3) = 1/2 ⇒ θ = 30° bulunur. Buradan r/a = sin30° = 1/2 elde edilir ve açınım merkez açısı α = 360·(1/2) = 180 derece olur.'),
  ('Bir dik yamuğun alt tabanı 12 cm, üst tabanı 6 cm ve yüksekliği 8 cm\'dir. Bu dik yamuğun dik olmayan yan kenarını taşıyan doğru etrafında 360 derece döndürülmesiyle oluşan döner cismin hacmi kaç π santimetreküptür?', '2688/5', ['3888/5', '2496/5', '3456/5'], 'Köşeleri A(0,0), B(12,0), C(6,8), D(0,8) alınırsa BC doğrusu 4x + 3y - 48 = 0 olur. Yamuk ABC (alanı 48, G₁(6, 8/3), d₁ = 16/5) ve ACD (alanı 24, G₂(2, 16/3), d₂ = 24/5) üçgenlerine ayrılır. Pappus teoreminden V = 2π·(48·16/5 + 24·24/5) = 2688π/5 cm³ bulunur.'),
  ('Yüksekliği 12 cm ve taban yarıçapı 9 cm olan dik dairesel koni biçimindeki kapalı kap, tepe noktası aşağıda ve ekseni düşey olacak biçimde tutulurken içinde 8 cm yüksekliğinde su bulunmaktadır. Kap ters çevrilip tabanı yatay zemine oturtulursa suyun yerden yüksekliği kaç santimetre olur?', '12 - 4·³√19', ['12 - 2·³√19', '12 - 4·³√8', '8 - 2·³√19'], 'Tepe aşağıdayken su yüksekliği 8 cm olduğundan benzerlik oranı 2/3 ve su hacmi tüm hacmin 8/27\'sidir. Ters çevrilince üstteki boş koninin hacmi tüm hacmin 19/27\'si olur. (h_boş / 12)³ = 19/27 ⇒ h_boş = 4·³√19 cm bulunur; su yüksekliği 12 - 4·³√19 cm olur.'),
  ('Taban yarıçapı 5 cm olan yeterince uzun bir dik dairesel silindir, ekseniyle 60 derecelik açı yapan bir düzlemle alt ve üst tabanlara değmeden kesiliyor. Kesit düzleminin silindir yan yüzeyiyle oluşturduğu eğri üzerindeki en alt nokta ile en üst nokta arasındaki eksene paralel uzaklık kaç santimetredir?', '10 / √3', ['10√3', '5√3', '20 / √3'], 'Kesit düzlemi silindir ekseniyle 60° açı yapıyorsa taban düzlemiyle 30° açı yapar. Silindirin çapı 2r = 10 cm olduğundan en alt ve en üst noktalar arasındaki eksene paralel uzaklık h\' = 10 · tan30° = 10 / √3 cm olur.'),
  ('Merkez açısı 120 derece ve yarıçapı 12 cm olan bir daire diliminden, aynı merkezli ve yarıçapı 3 cm olan küçük daire dilimi kesilip atılıyor. Kalan halka dilimi kıvrılarak bir kesik dik koni oluşturulduğuna göre bu kesik koninin hacmi kaç π santimetreküptür?', '42√2', ['63√2', '21√2', '84√2'], 'Üst yarıçap r = 3·(120/360) = 1 cm, alt yarıçap R = 12·(120/360) = 4 cm ve kesik koni ana doğrusu a = 12 - 3 = 9 cm\'dir. Yükseklik h = √(9² - (4 - 1)²) = 6√2 cm olur. Hacim V = (1/3)·π·6√2·(16 + 4 + 1) = 42√2·π cm³ bulunur.'),
  ('Taban yarıçapı ve ana doğru uzunluğu santimetre cinsinden birer tam sayı olan dik dairesel koninin yan yüzeyi açıldığında oluşan daire diliminin çevresi 28 + 8π santimetredir. Buna göre bu koninin hacmi kaç π santimetreküptür?', '32√5', ['64√5', '96√5 / 3', '16√5'], 'Daire diliminin çevresi 2a + 2πr = 28 + 8π olup a ve r tam sayı olduğundan 2a = 28 ⇒ a = 14 cm ve 2πr = 8π ⇒ r = 4 cm bulunur. Yükseklik h = √(14² - 4²) = √180 = 6√5 cm olur. Koni hacmi (1/3)·π·4²·6√5 = 32√5·π cm³ elde edilir.'),
  ('Ayrıtı 6 cm olan bir küpün köşelerinden biri O olmak üzere, O\'dan çıkan üç ayrıtın diğer uçları A, B, C birleştirilerek oluşturulan OABC üçgen piramidinin O köşesinden ABC yüzüne inilen yüksekliği kaç cm\'dir?', '2√3', ['3√3 santimetre', '2√2 santimetre', '3√2 santimetre'], 'OABC hacmi (1/6)·6·6·6 = 36; ABC kenarı 6√2 olan eşkenar üçgenin alanı 18√3 olduğundan h = (3·36)/(18√3) = 2√3 cm olur.'),
  ('Düzgün yirmiyüzlünün (ikosahedron) toplam ayrıt sayısı E ve köşe sayısı V olduğuna göre E - V farkı kaçtır?', '18', ['12 fark değeri', '20 fark değeri', '16 fark değeri'], 'F=20 üçgen yüz için E=(20·3)/2=30, Euler\'den V=2+30-20=12; dolayısıyla E - V = 30 - 12 = 18 olur.'),
  ('Yarıçapı 5 cm olan kürenin içine yerleştirilebilecek maksimum hacimli dik dairesel silindirin yüksekliği kaç cm\'dir?', '10/√3', ['5√2 santimetre uzunluk', '5√3 santimetre uzunluk', '10/√2 santimetre uzunluk'], 'Silindir hacmi V = 2π(R² - (h/2)²)(h/2); türev sıfırlanınca h = 2R/√3 = 10/√3 cm bulunur.'),
  ('Düzgün dörtyüzlünün içine teğet olan kürenin yarıçapının, aynı dörtyüzlüyü çevreleyen kürenin yarıçapına oranı kaçtır?', '1/3', ['1/2 yarıçap oranı', '1/4 yarıçap oranı', '√3/3 yarıçap oranı'], 'Düzgün dörtyüzlüde iç teğet yarıçap r = h/4, çevrel yarıçap R = 3h/4 olduğundan r/R = 1/3 olur.'),
  ('Yarıçapı 10 cm olan küre şeklindeki bir katı cismin merkezinden geçen ve yarıçapı 6 cm olan silindirik bir delik açılıyor. Geriye kalan halka şeklindeki katı cismin hacmi kaç π cm³\'tür?', '2048/3', ['1024/3 π santimetreküp', '512 π santimetreküp', '1600/3 π santimetreküp'], 'Peçete halkası teoremine göre kalan hacim yalnızca yüksekliğe bağlıdır: h = 2√(10²-6²) = 16 cm; V = πh³/6 = π·4096/6 = 2048π/3 cm³.'),
  ('İçbükey olmayan bir çokyüzlünün yüzleri yalnızca düzgün beşgen ve düzgün altıgenlerden oluşmakta ve her köşede tam 3 yüz birleşmektedir. Euler teoremine göre bu çokyüzlüde kesinlikle kaç tane beşgen yüz bulunur?', '12', ['20 adet beşgen yüz', '10 adet beşgen yüz', '14 adet beşgen yüz'], 'F = p+h, 2E = 5p+6h, 3V = 5p+6h denklemleri V-E+F=2\'de yerine konunca p = 12 elde edilir.'),
  ('Bir eşkenar üçgenin bir kenarı 6 cm\'dir. Bu üçgen kendi ağırlık merkezinden geçen ve bir kenarına paralel olan doğru etrafında 360 derece döndürülmüyor; bunun yerine bir yüksekliği etrafında 360 derece döndürülürse oluşan koninin hacmi kaç π cm³ olur?', '9√3', ['18√3 π santimetreküp', '27√3 π santimetreküp', '12√3 π santimetreküp'], 'Yarıçap r=3 cm, yükseklik h=3√3 cm olan dik koni oluşur; V = (1/3)π·9·3√3 = 9√3 π cm³ bulunur.'),
  ('Yarıçapı R olan bir kürenin içine çizilen düzgün altıyüzlünün (küpün) hacminin kürenin hacmine oranı aşağıdakilerden hangisidir?', '2/(π√3)', ['4/(3π√3) hacim oranı', '3/(2π√3) hacim oranı', '1/(π√2) hacim oranı'], 'Küp köşegeni a√3 = 2R ise a = 2R/√3; V_küp / V_küre = (8R³/3√3) / (4πR³/3) = 2/(π√3) olur.'),
  ('Uzayda iki düzlemin ara kesit doğrusu d\'dir. Birinci düzlem üzerinde d\'ye uzaklığı 6 cm olan A noktasından ikinci düzleme indirilen dikmenin ayağı H ve AH = 3√3 cm ise iki düzlem arasındaki dar açı kaç derecedir?', '60', ['30 derecelik dar açı', '45 derecelik dar açı', '75 derecelik dar açı'], 'Üç dikme teoreminden sinα = AH / 6 = (3√3)/6 = √3/2 olduğundan iki düzlem arası dar açı 60° bulunur.'),
  ('Tabanları 2 cm ve 6 cm, yüksekliği 4 cm olan bir ikizkenar yamuk, uzun tabanı (6 cm) etrafında 360 derece döndürülürse oluşan katı cismin hacmi kaç π cm³ olur?', '160/3', ['64 π santimetreküp', '128/3 π santimetreküp', '80 π santimetreküp'], 'Ortada r=4, h=2 silindir (32π) ve iki uçta r=4, h=2 koniler (2·32π/3 = 64π/3); toplam 32π + 64π/3 = 160π/3 cm³.'),
  ('Ayrıtı 2√3 cm olan düzgün dörtyüzlünün (tetrahedron) hacmi kaç cm³\'tür?', '2√6', ['4√6 santimetreküp', '6√2 santimetreküp', '3√6 santimetreküp'], 'Düzgün dörtyüzlü hacmi a³√2/12 = (24√3·√2)/12 = 2√6 cm³ bulunur.'),
  ('Bir düzgün dörtyüzlünün herhangi iki yüzü arasındaki iki düzlemli (dihedral) açının kosinüsü kaçtır?', '1/3', ['1/2 kosinüs değeri', '√3/3 kosinüs değeri', '2/3 kosinüs değeri'], 'Yüz yüksekliği a√3/2 olan iki yüz arasında kosinüs teoremiyle cosθ = ((3/4)+(3/4)-1) / (2·3/4) = (1/2)/(3/2) = 1/3 olur.'),
  ('Uzayda ayrıt uzunlukları 2 cm, 3 cm ve 6 cm olan dikdörtgenler prizmasının bir köşesinden geçen cisim köşegeni ile 6 cm\'lik ayrıt arasındaki açının kosinüsü kaçtır?', '6/7', ['3/7 kosinüs değeri', '2/7 kosinüs değeri', '5/7 kosinüs değeri'], 'Cisim köşegeni √(4+9+36) = 7 cm ve komşu dik kenar 6 cm olduğundan cosθ = 6/7 bulunur.'),
  ('Ayrıtı 4 cm olan bir küpün içindeki ABCD-EFGH köşelerinden B, D, E ve G köşeleri birleştirilerek oluşturulan BDEG düzgün dörtyüzlüsünün hacmi kaç cm³\'tür?', '64/3', ['32 santimetreküp', '32/3 santimetreküp', '16√2 santimetreküp'], 'Küp hacminden 4 köşe piramidi çıkarılır: 64 - 4·(1/6)·64 = 64/3 cm³ bulunur.'),
  ('Taban çevresi 16 cm olan düzgün kare piramidin taban köşelerinden biri A, karşı köşesi C\'dir. Yanal ayrıt uzunluğu 4 cm olan bu piramidin A noktasından başlayıp komşu iki yan yüz üzerinden geçerek C noktasına ulaşan en kısa yürüyüş yolu kaç cm\'dir?', '4√3', ['4√2 santimetre uzunluk', '8 santimetre uzunluk', '6√2 santimetre uzunluk'], 'Yanal yüzler kenarı 4 cm olan eşkenar üçgenlerdir; iki komşu yüz açıldığında 60°+60°=120° açılı eşkenar dörtgenin uzun köşegeni 4√3 cm olur.'),
  ('Yüksekliği 12 cm ve taban yarıçapı 5 cm olan bir dik koni, tabanından 6 cm yukarıdan tabana paralel bir düzlemle kesiliyor. Kesilen üstteki küçük koninin hacmi kaç π cm³\'tür?', '25/2', ['25 π santimetreküp', '50/3 π santimetreküp', '75/4 π santimetreküp'], 'Üst koninin yüksekliği 6 cm, yarıçapı 5/2 cm; hacmi (1/3)π·(25/4)·6 = 25π/2 cm³ olur.'),
  ('Uzayda bir P düzlemi ile 30 derece açı yapan 10 cm uzunluğundaki bir AB doğru parçasının P düzlemi üzerindeki dik izdüşüm uzunluğu kaç cm\'dir?', '5√3', ['5 santimetre uzunluk', '5√2 santimetre uzunluk', '10√3/3 santimetre'], 'Dik izdüşüm uzunluğu |AB|·cos30° = 10·(√3/2) = 5√3 cm olarak hesaplanır.'),
];
